);

CREATE TABLE IF NOT EXISTS project_principal_memberships (
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    participant_actor_id TEXT NOT NULL,
    source_membership_id TEXT NOT NULL,
    role TEXT NOT NULL,
