    UNIQUE (workspace_id,bcs_message_id,target_order)
);

CREATE TABLE IF NOT EXISTS workspace_task_dispatch_outbox (
    dispatch_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    task_id TEXT NOT NULL,
    attempt_id TEXT,
    plan_id TEXT,
    plan_node_id TEXT,
    user_id TEXT NOT NULL,
    agent_id TEXT NOT NULL,
    workspace_agent_binding_id TEXT NOT NULL,
    bot_uuid TEXT NOT NULL,
    group_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL,
    delivery_request_id TEXT NOT NULL,
    task_title TEXT NOT NULL,
    task_description TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    attempt_count INTEGER NOT NULL DEFAULT 0,
    max_attempts INTEGER NOT NULL DEFAULT 8,
    next_attempt_at_ms INTEGER NOT NULL DEFAULT 0,
    lease_owner TEXT,
    lease_expires_at_ms INTEGER,
    lease_generation INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    delivered_at_ms INTEGER,
    created_at_ms INTEGER NOT NULL,
    PRIMARY KEY (dispatch_id),
    UNIQUE (delivery_request_id)
);

CREATE TABLE IF NOT EXISTS workspace_contexts (
    user_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    revision INTEGER NOT NULL,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id)
);

CREATE TABLE IF NOT EXISTS workspace_context_events (
    event_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    actor_api_key_id TEXT,
    from_tenant_id TEXT,
    from_project_id TEXT,
    to_tenant_id TEXT NOT NULL,
    to_project_id TEXT NOT NULL,
    revision INTEGER NOT NULL,
    idempotency_key TEXT NOT NULL,
    value_json TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    request_hash TEXT NOT NULL,
    PRIMARY KEY (event_id),
    UNIQUE (user_id,idempotency_key),
    UNIQUE (user_id,revision)
);

CREATE TABLE IF NOT EXISTS workspace_context_outbox (
    outbox_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    event_type TEXT NOT NULL,
    stream_name TEXT NOT NULL,
    event_sequence INTEGER NOT NULL,
    payload_json TEXT NOT NULL,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    actor_api_key_id TEXT,
    idempotency_key TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    attempt_count INTEGER NOT NULL DEFAULT 0,
    max_attempts INTEGER NOT NULL DEFAULT 12,
    next_attempt_at TEXT,
    lease_owner TEXT,
    lease_expires_at TEXT,
    dispatched_at TEXT,
    last_error TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (outbox_id),
    UNIQUE (user_id,idempotency_key),
    UNIQUE (user_id,event_sequence)
);

CREATE TABLE IF NOT EXISTS workspace_file_operations (
    operation_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    file_id TEXT NOT NULL,
    actor_id TEXT NOT NULL,
    action TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    request_hash TEXT NOT NULL,
    state TEXT NOT NULL,
    staged_handle_json TEXT,
    ready_handle_json TEXT,
    checksum_sha256 TEXT,
    size_bytes INTEGER,
    last_error TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TEXT,
    PRIMARY KEY (operation_id),
    UNIQUE (workspace_id,file_id),
    UNIQUE (workspace_id,actor_id,idempotency_key)
);

CREATE TABLE IF NOT EXISTS workspace_file_compensations (
    compensation_id TEXT NOT NULL,
    operation_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    file_id TEXT NOT NULL,
    compensation_kind TEXT NOT NULL,
    object_handle_json TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    attempt_count INTEGER NOT NULL DEFAULT 0,
    max_attempts INTEGER NOT NULL DEFAULT 20,
    next_attempt_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lease_owner TEXT,
    lease_expires_at TEXT,
    last_error TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TEXT,
    PRIMARY KEY (compensation_id),
    UNIQUE (operation_id,compensation_kind)
);

CREATE TABLE IF NOT EXISTS workspace_objective_task_projections (
    projection_id TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    objective_id TEXT NOT NULL,
